create table "irl_user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" boolean not null, "image" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null, "handle" text unique, "visibility" text, "discoverable" boolean, "adultFrom" text);

create table "irl_session" ("id" text not null primary key, "expiresAt" timestamptz not null, "token" text not null unique, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null, "ipAddress" text, "userAgent" text, "userId" text not null references "irl_user" ("id") on delete cascade);

create table "irl_account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "irl_user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, "scope" text, "password" text, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz not null);

create table "irl_verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" timestamptz not null, "createdAt" timestamptz default CURRENT_TIMESTAMP not null, "updatedAt" timestamptz default CURRENT_TIMESTAMP not null);

create table "irl_passkey" ("id" text not null primary key, "name" text, "publicKey" text not null, "userId" text not null references "irl_user" ("id") on delete cascade, "credentialID" text not null, "counter" integer not null, "deviceType" text not null, "backedUp" boolean not null, "transports" text, "createdAt" timestamptz, "aaguid" text);

create table "irl_rate_limit" ("id" text not null primary key, "key" text not null unique, "count" integer not null, "lastRequest" bigint not null);

create index "irl_session_userId_idx" on "irl_session" ("userId");

create index "irl_account_userId_idx" on "irl_account" ("userId");

create index "irl_verification_identifier_idx" on "irl_verification" ("identifier");

create index "irl_passkey_userId_idx" on "irl_passkey" ("userId");

create index "irl_passkey_credentialID_idx" on "irl_passkey" ("credentialID");
